code.solutionCode:
address private owner;
uint256 private balance;

function withdraw() external {
    require(msg.sender == owner, "not owner");
    uint256 amount = balance;
    balance = 0;
    (bool ok, ) = payable(msg.sender).call{value: amount}("");
    require(ok, "send failed");
}
